// one layer as a base functor, its fixed point, then cata derives the recursion
sealed trait ListF[+A, +R]
case object NilF extends ListF[Nothing, Nothing]
case class ConsF[A, R](head: A, tail: R) extends ListF[A, R]

type ListR[A] = Fix[ListF[A, *]]

val sumAlg: Algebra[ListF[Int, *], Int] = Algebra {        // F[Int] => Int
  case NilF          => 0
  case ConsF(h, acc) => h + acc
}
